import * as mongoose from 'mongoose';
import { PaginateModel } from 'mongoose';
import * as mongoosePaginate from 'mongoose-paginate';
import { ICar } from '../interfaces';

export enum ChoicesStatusCar {
  active = 'active',
  pending = 'pending',
  inventory = 'inventory'
}

export const choicesStatusCar = [
  ChoicesStatusCar.pending,
  ChoicesStatusCar.active,
  // generated by inventary
  ChoicesStatusCar.inventory
];

export interface ICarModel extends ICar, mongoose.Document {
}

export const carSchema = new mongoose.Schema({
  vin: {
    type: String,
    trim: true
  },
  vin2: {
    type: String,
    trim: true
  },
  internalNumber: {
    type: String,
    default: '',
    trim: true
  },
  patent: {
    type: String,
    default: '',
    trim: true
  },
  engineNumber: {
    type: String,
    default: '',
    trim: true
  },
  engineSize: {
    type: String,
    default: ''
  },
  driveType: {
    type: String,
    default: '',
  },
  destination: {
    type: String
  },
  property: {
    type: String,
    trim: true,
    uppercase: true
  },
  type: {
    type: String,
    trim: true
  },
  brand: {
    type: String
  },
  denomination: {
    type: String
  },
  material: {
    type: String
  },
  color: {
    type: String,
    default: ''
  },
  invoice: {
    type: String,
    default: ''
  },
  businessYear: {
    type: String,
  },
  manufacturingYear: {
    type: String,
  },
  price: {
    type: String,
  },
  insurancePrice: {
    type: String,
  },
  weight:{
    type: String,
  },
  countryOrigin: {
    type: String,
  },
  gas:{
    type: String,
  },
  ap:{
    type: String,
  },
  entry: {
    type: String,
    default: ''
  },
  client: {
    type: String,
    default: ''
  },
  bl: {
    type: String,
    default: ''
  },
  isExhibition: {
    type: Boolean,
    default: false
  },
  team: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'Team'
  },
  company: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'Company'
  },
  imported: {
    type: Boolean,
    default: true
  },
  lastForm: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'Participant',
    default: null
  },
  status: {
    type: String,
    enum: choicesStatusCar,
    required: true,
    default: ChoicesStatusCar.active
  },
  createdBy: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'User',
    default: null
  }
}, {
  timestamps: true
});

// text search
carSchema.index({
  team: 1, denomination: 'text', material: 'text', brand: 'text'
}, {
  weights: {
    material: 3,
    denomination: 2,
    brand: 1
  }
});

carSchema.index({
  team: 1, status: 1, createdAt: -1
});
carSchema.index({
  team: 1, lastForm: -1
});

carSchema.virtual('participants', {
  ref: 'Participant', // The model to use
  localField: '_id', // Find field in this model
  foreignField: 'car', // is equal to field in another model
  justOne: false
});

carSchema.virtual('inventories', {
  ref: 'InventoryCar', // The model to use
  localField: '_id', // Find field in this model
  foreignField: 'car', // is equal to field in another model
  justOne: false
});

carSchema.set('toObject', { virtuals: true });
carSchema.set('toJSON', { virtuals: true });

carSchema.statics.findOneOrCreate = function(condition: any, create: any): Promise<ICarModel> {
  const model = this;
  return new Promise((resolve, reject) => {
    model.findOne(condition, (err: any, result: ICarModel) => {
      if (err) {
        return reject(err);
      }
      if (result) {
        return resolve(result);
      }
      model.create(create, (err: any, result: ICarModel) => {
        if (err) {
          return reject(err);
        }
        return resolve(result);
      });
    });
  });
};

carSchema.plugin(mongoosePaginate);

export type CarSchema = mongoose.Model<ICarModel> & PaginateModel<ICarModel> & {
  findOneOrCreate(condition: any, create: any): Promise<ICarModel>
};

const Car = mongoose.model<ICarModel, CarSchema>('Car', carSchema);

export default Car;
